export function updateAnimationIKRuntime(editor,state){const out=editor.element.querySelector('[data-anim-ik-runtime]'),s=state?.ik?.find(s=>s.node===editor.selection),text=s?(s.plant?.missingAnchor?'접촉 표면 없음 · '+s.plant.missingAnchor:s.missingActor?'목표 없음 · '+s.missingActor:'오차 '+s.error.toFixed(4)+' · '+s.iterations+'회 · '+Math.round(s.weight*100)+'%'+(s.groundPelvis?.active?' · 골반 '+s.groundPelvis.applied.toFixed(3)+' m · 지지 '+s.groundPelvis.hits+(s.groundPelvis.blocked?' · 위치 고정':''):'')+(s.ground?(s.ground.hit?' · 지면 '+s.ground.slope.toFixed(1)+'°':s.ground.active?' · '+(s.ground.reason==='slope'?'허용 경사 초과':'지면 없음'):' · 지면 보정 대기'):'')+(s.pole?.active?' · 관절 '+s.pole.angle.toFixed(1)+'°'+(s.pole.stabilized?' · 방향 유지':''):'')+(s.autoPlant?.active?' · 자동 접촉 '+(s.autoPlant.phase==='planted'?'고정':s.autoPlant.phase==='settling'?'대기':s.autoPlant.phase==='height'?'높이 초과':'이동 중'):'')+(s.stride?.active?' · 보폭 '+s.stride.scale.toFixed(2)+(s.stride.plantOverride?' · 고정 우선':''):'')+(s.plant&&s.plant.weight>0?' · '+(s.plant.active?'발 고정':'발 해제')+' '+Math.round(s.plant.weight*100)+'%':'')):'';if(out&&out.textContent!==text)out.textContent=text;for(const field of editor.element.querySelectorAll('[data-anim-goal-runtime]')){const row=s?.effectors?.[Number(field.dataset.animGoalRuntime)],value=row?(row.missingActor?'목표 없음 · '+row.missingActor:'오차 '+row.error.toFixed(4)+' · '+Math.round(row.weight*100)+'%'):'';if(field.textContent!==value)field.textContent=value;}}
